  const routeFiles={whatsapp:'whatsapp.html',leads:'leads.html',agente:'agente.html',cotacao:'cotacao.html',orcamentos:'orcamentos.html',orcamento:'orcamento.html',integracoes:'integracoes.html',plano:'plano.html',seguranca:'seguranca.html',faturamento:'faturamento.html',inicio:'portal.html',agencia:'agencia.html',clientes:'clientes.html',cliente:'cliente.html',viagem:'viagem.html',agenda:'agenda.html',financeiro:'financeiro.html',roteiros:'roteiros.html',roteiro:'roteiro.html',studio:'studio.html',documentos:'documentos.html',documento:'documento.html',configuracoes:'configuracoes.html',travelmatch:'travelmatch.html',vuei:'vuei.html'};
  function routeHref(route){const [name,id]=route.split('/');return (routeFiles[name]||'portal.html')+(id?'?id='+encodeURIComponent(id):'');}
